ATLAS_P("K60","INSTALANDING.AI \u00b7 Model Capture Console\n\nThe page below is the build. Use it as the starting point, not as inspiration:\n- Keep its layout, design values (colours, type, spacing, radii) and motion exactly as they are.\n- Replace the fictional brand, copy, names and numbers with mine.\n- If I name a stack (React, Next.js, Vue, Svelte, Astro...), convert it faithfully to that stack;\n  otherwise ship it as this one HTML file.\n- Read the MAP and ADAPTING notes in its header comment before you edit.\n- Check it in a real browser: no console errors, no horizontal scroll at 390px, reduced motion respected.\n\nCredit: keep this line as a comment at the top of the file you produce:\nModel Capture Console \u00b7 INSTALANDING.AI (MIT) \u00b7 https://instalanding.ai/prompt/model-capture-console\n\nmaverick-console.html:\n```html\n<!doctype html>\n<!--\n  INSTALANDING.AI \u00b7 Model Capture Console\n  slug     model-capture-console\n  prompt   https://instalanding.ai/p/model-capture-console.txt   (the one-shot brief this file was built from)\n  page     https://instalanding.ai/prompt/model-capture-console\n  license  MIT. Fictional brand; replace names, copy and numbers before shipping.\n\n  MAP\n  tokens    :root custom properties at the top of <style>: shell --void/--shell/--edge, inspector\n            --panel/--ink (redefined under .console[data-skin=\"dark\"]), signal --indigo/--cyan/--rose,\n            --bar/--sb (fold maths), --display Archivo / --mono JetBrains Mono (Google Fonts)\n  sections  topbar, console, status-bar\n  scripts   one inline IIFE, no libraries: LAYERS/STEPS/CHECKPOINTS data, tablist + arrow keys,\n            inspector skin toggle, overview rail, anatomy hotspots, timeline pager, eval meters,\n            trace transport + capture log; a second IIFE ties the topbar buttons to the tabs and ticks the clock\n  assets    none: CSS panels plus inline SVG (subject portrait, layer stack, icons, sparklines)\n\n  ADAPTING\n  - The fold is exact: --bar is the 60px topbar plus its 1px border, and section, shell and grid all\n    carry min-height:0. Drop one and the grid hands its overflow to the page instead of the panel.\n  - The skin toggle writes data-skin on #consoleBox (the console's own id, not the section's #console);\n    the dock is styled from shell tokens on purpose because --ink/--panel flip with the skin.\n  - Anatomy hotspots are placed from LAYERS data (left in % of #figInner, top scaled to 388px), never\n    measured: that tab starts display:none and measures zero width.\n  - Topbar buttons work by clicking the tab whose id is in their data-tab; keep those ids in step.\n-->\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\" />\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n<title>Maverick \u2014 open the model up</title>\n<meta name=\"description\" content=\"A capture console for inspecting a language model: pull it apart layer by layer, scrub a real trace, read the evals. Every panel is CSS and inline SVG \u2014 no images, no libraries.\" />\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\" />\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin />\n<link href=\"https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;600;700;800;900&family=JetBrains+Mono:wght@400;500;700&display=swap\" rel=\"stylesheet\" />\n<style>\n/* ============================================================\n   MAVERICK \u00b7 capture console\n   A dark scanline shell \u2014 the VHS case-file frame, its skewed\n   tabs and its transport \u2014 wrapped around a light inspector\n   panel built from big rounded cards and hotspot points.\n   One file, no images, no libraries.\n   ============================================================ */\n\n:root {\n  --bar: 61px; /* topbar: 60px of row plus its 1px border */\n  --sb: 30px;  /* status bar at the foot of the app */\n  /* shell */\n  --void: #06070a;\n  --shell: #0b0d12;\n  --shell-2: #101319;\n  --shell-3: #161a22;\n  --edge: rgba(148, 163, 184, 0.14);\n  --edge-2: rgba(148, 163, 184, 0.3);\n\n  /* inspector, light by default \u2014 the switch flips it */\n  --panel: #f1f2f5;\n  --panel-2: #fafbfc;\n  --panel-3: #e4e6eb;\n  --ink: #0f1218;\n  --ink-2: #474d5a;\n  --ink-3: #868d9c;\n\n  /* signal */\n  --indigo: #6366f1;\n  --indigo-2: #8b8cf8;\n  --cyan: #22d3ee;\n  --rose: #f43f5e;\n  --amber: #f59e0b;\n  --lime: #84cc16;\n\n  --scan: rgba(148, 163, 184, 0.055);\n  --ease: cubic-bezier(0.2, 0.8, 0.2, 1);\n  --display: \"Archivo\", system-ui, sans-serif;\n  --mono: \"JetBrains Mono\", ui-monospace, monospace;\n}\n\n/* the inspector's own dark mode, from the source's light/dark switch */\n.console[data-skin=\"dark\"] {\n  --panel: #0c0e13;\n  --panel-2: #12151c;\n  --panel-3: #1a1e27;\n  --ink: #eef1f6;\n  --ink-2: #aab2c0;\n  --ink-3: #6b7383;\n}\n\n* { margin: 0; padding: 0; box-sizing: border-box; }\nhtml { scroll-behavior: smooth; }\nbody {\n  min-height: 100vh;\n  background: var(--void);\n  color: #e7eaf0;\n  font-family: var(--display);\n  -webkit-font-smoothing: antialiased;\n  overflow-x: hidden;\n}\nbutton { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; }\na { color: inherit; text-decoration: none; }\n.sr { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }\n\n/* page-wide scanline + vignette, the one bit of atmosphere */\nbody::before {\n  content: \"\";\n  position: fixed; inset: 0; z-index: 90; pointer-events: none;\n  background: repeating-linear-gradient(0deg, transparent 0 2px, var(--scan) 3px);\n}\nbody::after {\n  content: \"\";\n  position: fixed; inset: 0; z-index: 89; pointer-events: none;\n  background: radial-gradient(130% 90% at 50% 34%, transparent 46%, rgba(0, 0, 0, 0.66) 100%);\n}\n\n.wrap { width: min(1180px, 100% - 40px); margin: 0 auto; }\n\n/* ============================================================\n   CHROME\n   ============================================================ */\n.topbar {\n  position: sticky; top: 0; z-index: 80;\n  background: rgba(6, 7, 10, 0.84);\n  backdrop-filter: blur(12px);\n  -webkit-backdrop-filter: blur(12px);\n  border-bottom: 1px solid var(--edge);\n}\n.topbar .wrap { display: flex; align-items: center; justify-content: space-between; height: calc(var(--bar) - 1px); gap: 18px; }\n/* The left slot of a dashboard's bar is the view you are in, not a mark.\n   These live behind a sign-up: whoever is looking already knows whose\n   product it is, and a wordmark up here is the one thing that would make\n   it read as a landing page again. */\n.view {\n  font-family: var(--mono, ui-monospace, monospace);\n  font-size: 11px; letter-spacing: 0.18em; text-transform: uppercase;\n  white-space: nowrap;\n}\n.ver { font-family: var(--mono); font-size: 10px; letter-spacing: 0.1em; color: var(--ink-3); }\n.topnav button { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; padding: 0; }\n.topnav { display: flex; gap: 22px; font-family: var(--mono); font-size: 11px; letter-spacing: 0.12em; text-transform: uppercase; color: #8b93a3; }\n.topnav button:hover, .topnav button[aria-current=\"true\"] { color: var(--cyan); }\n\n.eyebrow {\n  display: inline-flex; align-items: center; gap: 9px;\n  font-family: var(--mono); font-size: 10.5px; font-weight: 500;\n  letter-spacing: 0.22em; text-transform: uppercase; color: var(--indigo-2);\n}\n.eyebrow::before { content: \"\"; width: 7px; height: 7px; border-radius: 50%; background: var(--rose); box-shadow: 0 0 9px var(--rose); animation: rec 1.6s infinite; }\n@keyframes rec { 50% { opacity: 0.25; } }\n\nh1, h2 { font-weight: 800; letter-spacing: -0.03em; line-height: 1.02; }\n\n/* ============================================================\n   HERO\n   ============================================================ */\n/* The console owns the fold, so the shell is exactly the viewport left\n   under the sticky topbar and everything inside it flexes to fit rather\n   than the page scrolling to reach it. dvh so a mobile URL bar sliding\n   away does not leave a 60px gap under the shell. */\n.console-view {\n  height: calc(100vh - var(--bar) - var(--sb));\n  height: calc(100dvh - var(--bar) - var(--sb));\n  min-height: 520px;\n  display: flex; flex-direction: column;\n  padding-bottom: 8px;\n}\n\n/* ---------- STATUS BAR ---------- */\n.statusbar {\n  position: relative; z-index: 60;\n  height: var(--sb);\n  display: flex; align-items: center; justify-content: space-between; gap: 18px;\n  padding: 0 18px;\n  background: rgba(6, 7, 10, 0.92);\n  border-top: 1px solid var(--edge);\n  font-family: var(--mono); font-size: 9.5px; letter-spacing: 0.08em;\n  color: #6b7383; white-space: nowrap; overflow: hidden;\n}\n.statusbar b { color: var(--cyan); font-weight: 700; letter-spacing: 0.16em; }\n.statusbar a { color: #8b93a3; border-bottom: 1px solid var(--indigo); }\n.statusbar a:hover { color: var(--cyan); }\n.sb-left { display: flex; align-items: center; gap: 8px; min-width: 0; overflow: hidden; text-overflow: ellipsis; }\n.sb-right { flex: none; }\n.sb-dot { flex: none; width: 6px; height: 6px; border-radius: 50%; background: var(--rose); box-shadow: 0 0 6px var(--rose); }\n@media (max-width: 860px) { .sb-right { display: none; } }\n.console-view > .wrap { flex: 1; display: flex; min-height: 0; }\n\n/* the pitch now follows the console instead of introducing it */\n.hero { text-align: center; padding: 92px 0 34px; }\n.hero h1 { font-size: clamp(36px, 6vw, 68px); margin: 18px auto 18px; max-width: 16ch; }\n.hero h1 em { font-style: normal; background: linear-gradient(92deg, var(--indigo-2), var(--cyan)); -webkit-background-clip: text; background-clip: text; color: transparent; }\n.hero > .wrap > p { max-width: 56ch; margin: 0 auto; font-size: 16.5px; line-height: 1.6; color: #8b93a3; }\n\n/* ============================================================\n   CONSOLE SHELL  (the case-file frame)\n   ============================================================ */\n.console-outer {\n  position: relative;\n  flex: 1; display: flex; flex-direction: column; min-height: 0;\n  padding: 14px;\n  background:\n    radial-gradient(70% 60% at 12% 6%, rgba(99, 102, 241, 0.16), transparent 42%),\n    radial-gradient(60% 60% at 90% 94%, rgba(34, 211, 238, 0.1), transparent 44%),\n    repeating-linear-gradient(0deg, var(--shell) 0 2px, var(--void) 3px, var(--shell-2) 4px);\n  border: 1px solid var(--edge-2);\n  outline: 1px dashed rgba(99, 102, 241, 0.34);\n  outline-offset: -7px;\n  overflow: hidden;\n}\n.console-outer::after {\n  content: \"REC \u25b8 00:14:02\";\n  position: absolute; right: 20px; bottom: 8px; z-index: 40;\n  font-family: var(--mono); font-size: 8px; letter-spacing: 0.24em; color: var(--rose);\n}\n.console {\n  flex: 1; min-height: 0;\n  display: grid;\n  grid-template-columns: 272px 1fr;\n  gap: 12px;\n  background: var(--shell);\n  border: 1px solid var(--edge);\n  padding: 8px;\n  box-shadow: inset 0 0 0 1px rgba(99, 102, 241, 0.12), 0 0 26px rgba(0, 0, 0, 0.7);\n}\n\n/* ---------- SIDEBAR ---------- */\n.side {\n  position: relative;\n  min-height: 0; overflow: auto;\n  display: flex; flex-direction: column;\n  padding: 15px;\n  background: repeating-linear-gradient(0deg, var(--shell-2) 0 3px, var(--void) 4px);\n  border: 1px solid var(--edge);\n  box-shadow: inset 0 0 0 1px rgba(99, 102, 241, 0.1);\n}\n/* the taped photo, now a generated capture frame */\n.subject {\n  position: relative;\n  padding: 8px 8px 24px;\n  background: var(--panel-2);\n  border: 1px solid #fff;\n  transform: rotate(-2deg);\n  box-shadow: 7px 7px 0 rgba(0, 0, 0, 0.3), 0 0 14px rgba(99, 102, 241, 0.3);\n  transition: transform 0.25s var(--ease);\n}\n.subject:hover { transform: rotate(-1deg) scale(1.02); }\n.subject::before {\n  content: \"\";\n  position: absolute; top: -11px; left: 54px;\n  width: 96px; height: 20px;\n  background: rgba(190, 197, 212, 0.5);\n  transform: rotate(4deg);\n  z-index: 4;\n}\n.subject-frame { position: relative; height: 168px; overflow: hidden; background: #05060a; }\n.subject-frame svg { width: 100%; height: 100%; display: block; }\n.subject-frame::after {\n  content: \"\";\n  position: absolute; inset: 0; z-index: 3; pointer-events: none;\n  background:\n    repeating-linear-gradient(0deg, rgba(255, 255, 255, 0.06) 0 1px, transparent 2px 4px),\n    linear-gradient(90deg, rgba(244, 63, 94, 0.16), transparent 40%, rgba(34, 211, 238, 0.12));\n  mix-blend-mode: screen;\n  animation: flick 0.2s infinite alternate;\n}\n@keyframes flick { to { opacity: 0.74; } }\n.subject-tag {\n  position: absolute; left: 14px; bottom: 5px; z-index: 5;\n  font-family: var(--mono); font-size: 8.5px; font-weight: 700;\n  letter-spacing: 0.18em; text-transform: uppercase; color: var(--rose);\n}\n.side-name {\n  margin: 14px 0 2px;\n  font-size: 40px; font-weight: 900; line-height: 0.86;\n  letter-spacing: -0.04em; text-transform: uppercase;\n  color: #fff;\n  transform: rotate(-2deg);\n}\n.side-name::after {\n  content: \"\";\n  display: block; width: 150px; height: 4px; margin-top: 9px;\n  background: linear-gradient(90deg, var(--indigo), var(--cyan), transparent);\n  transform: skew(-22deg);\n}\n.side-sub {\n  margin-top: 13px; padding: 7px 0;\n  border-top: 1px solid var(--edge); border-bottom: 1px solid var(--edge);\n  font-family: var(--mono); font-size: 9px; letter-spacing: 0.24em;\n  text-transform: uppercase; color: #8b93a3;\n}\n\n/* ---------- TRANSPORT ---------- */\n.transport {\n  margin-top: 18px; padding: 12px;\n  background: repeating-linear-gradient(0deg, var(--void) 0 3px, var(--shell-2) 4px);\n  border: 1px solid var(--edge);\n  box-shadow: inset 0 0 0 1px rgba(99, 102, 241, 0.12);\n}\n.transport-title {\n  display: inline-block; margin-bottom: 9px; padding: 4px 9px;\n  background: linear-gradient(90deg, var(--indigo), var(--cyan));\n  color: #07080b;\n  font-size: 15px; font-weight: 900; letter-spacing: 0.02em; text-transform: uppercase;\n  transform: rotate(-2deg);\n}\n.transport-read {\n  height: 44px; overflow: hidden; margin-bottom: 8px; padding: 6px 0;\n  border-top: 1px solid var(--edge); border-bottom: 1px solid var(--edge);\n  font-family: var(--mono); font-size: 9.5px; line-height: 1.45; color: #c3cad6;\n}\n.transport-btns { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; margin: 8px 0; }\n.tbtn {\n  padding: 6px 0; text-align: center;\n  border: 1px solid var(--edge-2); background: var(--void);\n  color: var(--indigo-2); font-family: var(--mono); font-size: 11px;\n  transition: 0.22s var(--ease);\n}\n.tbtn:hover { background: var(--indigo); color: #fff; transform: translateY(-1px); box-shadow: 0 0 14px rgba(99, 102, 241, 0.7); }\n.tbtn:focus-visible { outline: 2px solid var(--cyan); outline-offset: 2px; }\n#play.on { background: var(--indigo); color: #fff; box-shadow: 0 0 14px rgba(99, 102, 241, 0.7); }\n.track { height: 5px; margin: 8px 0; background: var(--shell-3); border: 1px solid var(--edge); overflow: hidden; }\n.track i { display: block; height: 100%; width: 0%; background: linear-gradient(90deg, var(--indigo), var(--cyan)); }\n.tmeta { display: flex; justify-content: space-between; font-family: var(--mono); font-size: 8.5px; letter-spacing: 0.1em; color: #8b93a3; text-transform: uppercase; }\n.temp { display: block; width: 100%; margin-top: 12px; appearance: none; -webkit-appearance: none; background: none; cursor: pointer; height: 18px; }\n.temp::-webkit-slider-runnable-track { height: 5px; background: linear-gradient(90deg, var(--indigo) 0 var(--f, 30%), var(--shell-3) var(--f, 30%)); border: 1px solid var(--edge); }\n.temp::-webkit-slider-thumb { -webkit-appearance: none; width: 14px; height: 14px; margin-top: -6px; border-radius: 50%; background: #fff; border: 2px solid var(--indigo); }\n.temp::-moz-range-track { height: 5px; background: var(--shell-3); border: 1px solid var(--edge); }\n.temp::-moz-range-progress { height: 5px; background: var(--indigo); }\n.temp::-moz-range-thumb { width: 12px; height: 12px; border-radius: 50%; background: #fff; border: 2px solid var(--indigo); }\n\n/* ---------- MAIN / TABS ---------- */\n.main {\n  position: relative; overflow: hidden;\n  min-height: 0; display: flex; flex-direction: column;\n  padding: 0 8px 8px;\n  background: repeating-linear-gradient(0deg, var(--void) 0 3px, var(--shell-2) 4px);\n  border: 1px solid var(--edge);\n  box-shadow: inset 0 0 0 1px rgba(99, 102, 241, 0.12), 0 14px 34px rgba(0, 0, 0, 0.7);\n}\n.main::before {\n  content: \"\"; position: absolute; left: 0; right: 8px; top: 51px; height: 2px; z-index: 9;\n  background: linear-gradient(90deg, transparent, var(--indigo), var(--cyan), transparent);\n}\n.tabs { height: 52px; flex: none; display: flex; align-items: flex-end; gap: 3px; padding-left: 14px; position: relative; z-index: 8; }\n.tabs button {\n  height: 40px; min-width: 96px;\n  background: linear-gradient(180deg, var(--shell-3), var(--void));\n  color: #c3cad6;\n  border: 1px solid var(--edge); border-bottom: none;\n  font-family: var(--mono); font-weight: 700; font-size: 9.5px;\n  letter-spacing: 0.1em; text-transform: uppercase;\n  transform: skew(-8deg);\n  transition: 0.22s var(--ease);\n  box-shadow: inset 0 0 0 1px rgba(99, 102, 241, 0.1);\n}\n.tabs button span { display: block; transform: skew(8deg); }\n.tabs button:hover, .tabs button[aria-selected=\"true\"] {\n  height: 52px;\n  background: linear-gradient(180deg, var(--indigo), #4f46e5);\n  color: #fff;\n  border-color: var(--indigo-2);\n  box-shadow: 0 0 14px rgba(99, 102, 241, 0.55), inset 0 0 0 1px rgba(255, 255, 255, 0.28);\n}\n.tabs button:focus-visible { outline: 2px solid var(--cyan); outline-offset: 2px; }\n\n/* ---------- THE CAPTURE LOG DOCK ----------\n   Shell furniture rather than panel content, so it keeps the shell's\n   palette when the inspector's light/dark switch flips --ink-*. */\n.dock {\n  flex: none; height: 168px; margin-top: 8px;\n  display: flex; flex-direction: column;\n  background: repeating-linear-gradient(0deg, var(--void) 0 3px, var(--shell-2) 4px);\n  border: 1px solid var(--edge);\n  box-shadow: inset 0 0 0 1px rgba(99, 102, 241, 0.12);\n}\n.dock-head {\n  flex: none; display: flex; align-items: center; justify-content: space-between; gap: 12px;\n  padding: 7px 10px; border-bottom: 1px solid var(--edge);\n  font-family: var(--mono); font-size: 9px; letter-spacing: 0.18em; text-transform: uppercase;\n}\n.dock-title { color: #fff; font-weight: 700; padding: 3px 9px; background: linear-gradient(90deg, var(--indigo), var(--cyan)); }\n.dock-meta { color: #6b7383; }\n.dock-log {\n  flex: 1; min-height: 0; overflow: auto; list-style: none;\n  padding: 7px 10px 9px; font-family: var(--mono); font-size: 10.5px; line-height: 1.7;\n}\n.dock-log li { display: grid; grid-template-columns: 58px 84px 1fr; gap: 10px; align-items: baseline; color: #8b93a3; }\n.dock-log .t { color: #565d6c; }\n.dock-log .k { font-size: 9px; letter-spacing: 0.1em; color: var(--cyan); }\n.dock-log li:last-child { color: #dfe4ee; }\n.dock-log li:last-child .k { color: var(--indigo-2); }\n\n/* ---------- THE SIDE MANIFEST ---------- */\n.manifest {\n  margin-top: auto; padding-top: 14px;\n  font-family: var(--mono); font-size: 9.5px; letter-spacing: 0.06em;\n}\n.manifest dl { display: grid; grid-template-columns: auto 1fr; gap: 4px 10px; }\n.manifest dt { color: #565d6c; text-transform: uppercase; letter-spacing: 0.14em; font-size: 8.5px; align-self: center; }\n.manifest dd { text-align: right; color: #aab2c0; }\n.manifest-rule { height: 1px; margin-bottom: 11px; background: linear-gradient(90deg, var(--indigo), transparent); }\n\n/* ---------- THE INSPECTOR PANEL ---------- */\n.panel {\n  position: relative;\n  flex: 1; min-height: 0;\n  background: var(--panel);\n  border: 1px solid var(--edge);\n  overflow: hidden;\n  transition: background 0.35s var(--ease);\n}\n.panel.glitch { animation: gl 0.26s; }\n@keyframes gl {\n  0% { transform: translateX(0); } 20% { transform: translateX(-3px); }\n  40% { transform: translateX(3px); } 60% { transform: translateX(-1px); } 100% { transform: translateX(0); }\n}\n.panel-inner { height: 100%; overflow: auto; padding: 18px 20px 26px; color: var(--ink); }\n/* A page fills the panel: the fold is a fixed height now, so a block that\n   simply stops halfway leaves a few hundred pixels of dead screen. Each\n   page either grows its main element or drops its last one to the floor. */\n.page { display: none; animation: fade 0.34s ease; }\n.page.on { display: flex; flex-direction: column; min-height: 100%; }\n#p-overview .stats, #p-timeline .dots, #p-trace .now { margin-top: auto; }\n#p-anatomy .anat, #p-behaviour .beh { flex: 1; min-height: 0; }\n@keyframes fade { from { opacity: 0; transform: translateY(10px); } }\n\n.panel-top { display: flex; align-items: center; justify-content: space-between; gap: 14px; margin-bottom: 16px; flex-wrap: wrap; }\n.panel-top h3 { font-size: 21px; font-weight: 800; letter-spacing: -0.02em; }\n.panel-top p { font-family: var(--mono); font-size: 10px; letter-spacing: 0.14em; text-transform: uppercase; color: var(--ink-3); margin-top: 3px; }\n/* the round icon buttons from the source */\n.round {\n  display: inline-grid; place-items: center;\n  width: 32px; height: 32px; border-radius: 50%;\n  background: var(--panel-2);\n  border: 1px solid var(--panel-3);\n  color: var(--ink-2);\n  transition: 0.22s var(--ease);\n}\n.round:hover { background: var(--indigo); border-color: var(--indigo); color: #fff; transform: translateY(-2px); box-shadow: 0 0 16px rgba(99, 102, 241, 0.6); }\n.round:focus-visible { outline: 2px solid var(--indigo); outline-offset: 3px; }\n.round svg { width: 15px; height: 15px; fill: none; stroke: currentColor; stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; }\n.round-set { display: flex; gap: 8px; }\n\n/* ---------- card rail (Medura) ---------- */\n.rail { display: grid; grid-template-columns: repeat(5, 1fr); gap: 10px; }\n.rcard {\n  position: relative;\n  display: flex; flex-direction: column; justify-content: center; align-items: center;\n  min-height: 190px; padding: 16px 10px;\n  background: var(--panel-2);\n  border: 1px solid var(--panel-3);\n  border-radius: 20px;\n  text-align: center;\n  transition: 0.28s var(--ease);\n}\n.rcard:hover, .rcard[aria-pressed=\"true\"] {\n  transform: translateY(-5px);\n  border-color: var(--indigo);\n  box-shadow: 0 0 0 1px var(--indigo), 0 18px 34px -18px rgba(99, 102, 241, 0.9), 0 0 34px -8px rgba(99, 102, 241, 0.55);\n}\n.rcard[aria-pressed=\"true\"] { background: linear-gradient(180deg, color-mix(in srgb, var(--indigo) 10%, var(--panel-2)), var(--panel-2)); }\n.rcard svg { width: 42px; height: 42px; fill: none; stroke: var(--indigo); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; margin-bottom: 14px; }\n.rcard b { font-size: 13.5px; font-weight: 700; letter-spacing: -0.01em; }\n.rcard span { margin-top: 4px; font-family: var(--mono); font-size: 9px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--ink-3); }\n.rcard em { margin-top: 9px; font-style: normal; font-family: var(--mono); font-size: 10px; color: var(--indigo); }\n\n/* ---------- captured-spans strip (the case file's evidence row) ---------- */\n.strip-wrap { position: relative; margin-top: 16px; }\n.strip-label {\n  position: absolute; top: -9px; left: 16px; z-index: 3;\n  padding: 3px 10px; border-radius: 6px;\n  background: var(--indigo); color: #fff;\n  font-family: var(--mono); font-size: 8.5px; letter-spacing: 0.16em; text-transform: uppercase;\n}\n.strip {\n  display: grid; grid-template-columns: repeat(6, 1fr); gap: 8px;\n  padding: 18px 12px 12px; border-radius: 18px;\n  background: repeating-linear-gradient(0deg, #07080b 0 3px, #0e1117 4px);\n  border: 1px solid rgba(99, 102, 241, 0.3);\n}\n.strip button {\n  position: relative; height: 62px; padding: 7px;\n  border: 1px solid rgba(99, 102, 241, 0.32);\n  background: #05060a; overflow: hidden;\n  transition: 0.24s var(--ease);\n}\n.strip button::after {\n  content: \"\"; position: absolute; inset: 0; pointer-events: none;\n  background: repeating-linear-gradient(0deg, transparent 0 3px, rgba(255, 255, 255, 0.06) 4px);\n}\n.strip button:nth-child(odd) { transform: rotate(-1deg); }\n.strip button:nth-child(even) { transform: rotate(1deg); }\n.strip button:hover, .strip button[aria-current=\"true\"] {\n  transform: rotate(0) translateY(-4px) scale(1.04); z-index: 4;\n  border-color: var(--indigo);\n  box-shadow: 0 0 6px var(--indigo), 0 0 20px rgba(99, 102, 241, 0.7);\n}\n.strip svg { width: 100%; height: 26px; display: block; }\n.strip svg polyline { fill: none; stroke: var(--cyan); stroke-width: 1.6; }\n.strip b { display: block; margin-top: 6px; font-family: var(--mono); font-size: 7.5px; letter-spacing: 0.12em; text-transform: uppercase; color: #aab2c0; }\n.strip em { font-style: normal; color: var(--indigo-2); }\n@media (max-width: 640px) { .strip { grid-template-columns: repeat(3, 1fr); } }\n\n/* ---------- stat strip ---------- */\n.stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-top: 14px; }\n.stat { padding: 13px 15px; border-radius: 16px; background: var(--panel-2); border: 1px solid var(--panel-3); }\n.stat dt { font-family: var(--mono); font-size: 9px; letter-spacing: 0.16em; text-transform: uppercase; color: var(--ink-3); }\n.stat dd { margin-top: 5px; font-size: 19px; font-weight: 800; font-variant-numeric: tabular-nums; }\n.stat dd small { font-size: 11px; font-family: var(--mono); color: var(--ink-3); margin-left: 3px; font-weight: 400; }\n\n/* ---------- ANATOMY: the diagram + hotspots ---------- */\n.anat { display: grid; grid-template-columns: 300px 1fr; gap: 20px; align-items: start; }\n.fig-inner { position: relative; }\n.figure {\n  position: relative;\n  border-radius: 22px;\n  background: linear-gradient(180deg, var(--panel-2), var(--panel-3));\n  border: 1px solid var(--panel-3);\n  padding: 16px;\n  min-height: 420px;\n}\n.figure svg.stack { width: 100%; height: 388px; display: block; }\n.stack .blk { fill: color-mix(in srgb, var(--indigo) 12%, transparent); stroke: var(--indigo); stroke-width: 1.4; }\n.stack .blk.dim { fill: color-mix(in srgb, var(--ink-3) 12%, transparent); stroke: var(--ink-3); stroke-width: 1.1; }\n.stack .spine { stroke: var(--indigo); stroke-width: 1.6; stroke-dasharray: 3 5; fill: none; opacity: 0.6; }\n.stack text { font-family: \"JetBrains Mono\", monospace; font-size: 8px; letter-spacing: 0.1em; fill: var(--ink-2); text-transform: uppercase; }\n/* hotspot point, straight from the source's Point component */\n.pt {\n  position: absolute;\n  width: 26px; height: 26px; margin: -13px 0 0 -13px;\n  border-radius: 50%;\n  display: grid; place-items: center;\n  transition: 0.24s var(--ease);\n}\n.pt::before {\n  content: \"\"; width: 9px; height: 9px; border-radius: 50%;\n  background: var(--indigo);\n  box-shadow: 0 0 0 4px color-mix(in srgb, var(--indigo) 26%, transparent);\n  transition: 0.24s var(--ease);\n}\n.pt::after {\n  content: \"\"; position: absolute; inset: 0; border-radius: 50%;\n  border: 1px solid var(--indigo); opacity: 0;\n  animation: ping 2.4s ease-out infinite;\n}\n@keyframes ping { 0% { transform: scale(0.45); opacity: 0.75; } 100% { transform: scale(1.7); opacity: 0; } }\n.pt:hover::before, .pt[aria-pressed=\"true\"]::before { width: 13px; height: 13px; box-shadow: 0 0 0 6px color-mix(in srgb, var(--indigo) 34%, transparent), 0 0 18px var(--indigo); }\n.pt:focus-visible { outline: 2px solid var(--indigo); outline-offset: 2px; }\n\n.detail { border-radius: 22px; background: var(--panel-2); border: 1px solid var(--panel-3); padding: 20px; min-height: 420px; }\n.detail-kicker { font-family: var(--mono); font-size: 9.5px; letter-spacing: 0.2em; text-transform: uppercase; color: var(--indigo); }\n.detail h4 { margin: 8px 0 4px; font-size: 26px; font-weight: 800; letter-spacing: -0.025em; }\n.detail .sub { font-family: var(--mono); font-size: 10px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--ink-3); }\n.detail p { margin-top: 14px; font-size: 13.5px; line-height: 1.65; color: var(--ink-2); }\n.detail dl { display: grid; grid-template-columns: repeat(2, 1fr); gap: 9px; margin-top: 18px; }\n.detail dl > div { padding: 11px 13px; border-radius: 13px; background: var(--panel); border: 1px solid var(--panel-3); }\n.detail dt { font-family: var(--mono); font-size: 8.5px; letter-spacing: 0.15em; text-transform: uppercase; color: var(--ink-3); }\n.detail dd { margin-top: 4px; font-size: 13px; font-weight: 700; }\n\n/* ---------- TIMELINE ---------- */\n.tl-cards { display: grid; grid-template-columns: repeat(2, 1fr); gap: 14px; }\n.tlc { border-radius: 20px; background: var(--panel-2); border: 1px solid var(--panel-3); padding: 18px; transition: 0.26s var(--ease); }\n.tlc:hover { transform: translateY(-4px); border-color: var(--indigo); box-shadow: 0 0 30px -10px rgba(99, 102, 241, 0.7); }\n.tlc-top { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; }\n.tlc-top b { font-size: 17px; font-weight: 800; letter-spacing: -0.02em; }\n.tlc-top span { font-family: var(--mono); font-size: 10px; color: var(--indigo); }\n.tlc p { margin-top: 9px; font-size: 12.5px; line-height: 1.6; color: var(--ink-2); }\n.tlc-bar { height: 4px; margin-top: 13px; border-radius: 3px; background: var(--panel-3); overflow: hidden; }\n.tlc-bar i { display: block; height: 100%; background: linear-gradient(90deg, var(--indigo), var(--cyan)); }\n/* the pill pagination from the source */\n.dots { display: flex; justify-content: center; margin-top: 18px; }\n.dots-pill { display: flex; gap: 9px; padding: 9px 15px; border-radius: 999px; background: var(--panel-2); border: 1px solid var(--panel-3); }\n.dots-pill button { width: 9px; height: 9px; border-radius: 50%; background: var(--panel-3); transition: 0.22s var(--ease); }\n.dots-pill button[aria-current=\"true\"] { background: var(--indigo); box-shadow: 0 0 10px var(--indigo); }\n.dots-pill button:focus-visible { outline: 2px solid var(--indigo); outline-offset: 3px; }\n\n/* ---------- BEHAVIOUR ---------- */\n/* fills the fixed-height panel rather than leaving a dead band under it */\n.beh { display: grid; grid-template-columns: 250px 1fr; gap: 16px; min-height: 424px; align-items: stretch; }\n.meters {\n  padding: 20px 17px 30px; border-radius: 20px;\n  background: repeating-linear-gradient(0deg, #07080b 0 3px, #0e1117 4px);\n  border: 1px solid rgba(99, 102, 241, 0.34);\n  color: #e7eaf0; position: relative; overflow: hidden;\n}\n.meters::after { content: \"\"; position: absolute; inset: 0; background: repeating-linear-gradient(0deg, transparent 0 3px, rgba(255, 255, 255, 0.05) 4px); pointer-events: none; }\n.meters h4 { font-size: 22px; font-weight: 900; letter-spacing: -0.02em; text-transform: uppercase; margin-bottom: 16px; color: #fff; }\n.meter { margin-bottom: 13px; font-family: var(--mono); font-size: 9px; letter-spacing: 0.14em; text-transform: uppercase; position: relative; z-index: 2; }\n.meter span { display: flex; justify-content: space-between; margin-bottom: 5px; color: #aab2c0; }\n.meter em { font-style: normal; color: #fff; }\n.meter .bar { height: 9px; padding: 2px; border: 1px solid rgba(99, 102, 241, 0.4); background: #05060a; }\n.meter .bar i { display: block; height: 100%; width: 0; background: linear-gradient(90deg, var(--indigo), var(--cyan)); box-shadow: 0 0 9px rgba(99, 102, 241, 0.8); transition: width 1s var(--ease); }\n.meter.warn .bar i { background: linear-gradient(90deg, var(--rose), var(--amber)); box-shadow: 0 0 9px rgba(244, 63, 94, 0.8); }\n.meter-id { position: absolute; left: 17px; bottom: 11px; font-family: var(--mono); font-size: 7px; letter-spacing: 0.24em; text-transform: uppercase; color: var(--indigo-2); z-index: 2; }\n.beh-notes { display: grid; gap: 12px; align-content: start; }\n.note { position: relative; border-radius: 18px; background: var(--panel-2); border: 1px solid var(--panel-3); padding: 16px 18px; }\n.note::before {\n  content: \"\"; position: absolute; top: -9px; left: 34px;\n  width: 78px; height: 17px; background: rgba(148, 163, 184, 0.34); transform: rotate(-3deg);\n}\n.note b { display: block; font-family: var(--mono); font-size: 9px; letter-spacing: 0.18em; text-transform: uppercase; color: var(--indigo); margin-bottom: 7px; }\n.note p { font-size: 12.5px; line-height: 1.6; color: var(--ink-2); }\n.stamp {\n  position: absolute; right: 12px; bottom: -10px;\n  padding: 4px 11px; border: 2px solid var(--rose); border-radius: 6px;\n  background: var(--panel-2); color: var(--rose);\n  font-size: 11px; font-weight: 900; letter-spacing: 0.16em; text-transform: uppercase;\n  transform: rotate(-5deg); opacity: 0.8;\n}\n\n/* ---------- TRACE ---------- */\n.trace-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px; }\n.step {\n  position: relative; text-align: left;\n  border-radius: 18px; background: var(--panel-2); border: 1px solid var(--panel-3);\n  padding: 15px 16px; transition: 0.26s var(--ease);\n}\n.step:hover { transform: translateY(-4px); border-color: var(--indigo); box-shadow: 0 0 30px -10px rgba(99, 102, 241, 0.7); }\n.step[aria-current=\"true\"] { border-color: var(--indigo); background: linear-gradient(180deg, color-mix(in srgb, var(--indigo) 12%, var(--panel-2)), var(--panel-2)); box-shadow: 0 0 0 1px var(--indigo); }\n.step-n { font-family: var(--mono); font-size: 9px; letter-spacing: 0.16em; color: var(--ink-3); }\n.step b { display: block; margin-top: 6px; font-size: 16px; font-weight: 800; letter-spacing: -0.02em; }\n.step p { margin-top: 7px; font-family: var(--mono); font-size: 10.5px; line-height: 1.55; color: var(--ink-2); }\n.step-meta { display: flex; gap: 12px; margin-top: 10px; font-family: var(--mono); font-size: 9px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--ink-3); }\n.now {\n  margin-top: 14px; padding: 14px 16px; border-radius: 16px;\n  background: repeating-linear-gradient(0deg, #07080b 0 3px, #0e1117 4px);\n  border: 1px solid rgba(99, 102, 241, 0.34);\n  color: #e7eaf0; font-family: var(--mono); font-size: 11px; letter-spacing: 0.06em;\n}\n\n/* ============================================================\n   PAGE SECTIONS BELOW THE CONSOLE\n   ============================================================ */\n.section { padding: 100px 0 0; scroll-margin-top: 64px; }\n.section-head { max-width: 52ch; margin-bottom: 44px; }\n.section-head h2 { margin: 16px 0 14px; font-size: clamp(28px, 4vw, 44px); }\n.section-head p { font-size: 15.5px; line-height: 1.65; color: #8b93a3; }\n\n.features { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; }\n.feat { padding: 24px; border: 1px solid var(--edge); background: linear-gradient(180deg, var(--shell-2), transparent); transition: 0.3s var(--ease); }\n.feat:hover { border-color: var(--indigo); transform: translateY(-4px); box-shadow: 0 0 34px -12px rgba(99, 102, 241, 0.8); }\n.feat-n { font-family: var(--mono); font-size: 10px; letter-spacing: 0.2em; color: var(--indigo-2); margin-bottom: 18px; }\n.feat h3 { font-size: 17px; font-weight: 700; margin-bottom: 9px; }\n.feat p { font-size: 13.5px; line-height: 1.62; color: #8b93a3; }\n\n.cta { margin-top: 96px; padding: 70px 26px; border: 1px solid var(--edge); text-align: center; background: radial-gradient(70% 120% at 50% 100%, rgba(99, 102, 241, 0.16), transparent 66%); }\n.cta h2 { font-size: clamp(28px, 4.6vw, 44px); margin-bottom: 15px; }\n.cta p { max-width: 46ch; margin: 0 auto 28px; font-size: 15.5px; line-height: 1.6; color: #8b93a3; }\n.btn {\n  display: inline-block; padding: 13px 26px;\n  border: 1px solid var(--indigo); color: #fff;\n  background: var(--indigo);\n  font-family: var(--mono); font-size: 12px; letter-spacing: 0.14em; text-transform: uppercase;\n  transition: 0.4s var(--ease);\n}\n.btn:hover { box-shadow: 0 0 6px var(--indigo), 0 0 22px var(--indigo), 0 0 52px rgba(99, 102, 241, 0.6); }\n\n.footer {\n  display: flex; justify-content: space-between; gap: 14px; flex-wrap: wrap;\n  margin-top: 44px; padding: 28px 0 44px; border-top: 1px solid var(--edge);\n  font-family: var(--mono); font-size: 10px; line-height: 1.85; color: #5b6373;\n}\n.footer a { color: #8b93a3; border-bottom: 1px solid var(--indigo); }\n.footer a:hover { color: var(--cyan); }\n\n/* ============================================================\n   RESPONSIVE\n   ============================================================ */\n/* stacked, the sidebar alone is most of a screen \u2014 let the page scroll */\n@media (max-width: 1000px) {\n  .console-view { height: auto; min-height: 0; }\n  .console-view > .wrap { display: block; }\n  .console-outer { display: block; }\n  .console { grid-template-columns: 1fr; }\n  .side { overflow: visible; }\n  .dock { height: 150px; }\n  .rail { grid-template-columns: repeat(3, 1fr); }\n  .anat, .beh { grid-template-columns: 1fr; }\n  .features { grid-template-columns: 1fr; }\n  .panel { height: auto; min-height: 520px; }\n  .panel-inner { overflow: visible; }\n}\n@media (max-width: 640px) {\n  .topnav, .ver { display: none; }\n  .rail { grid-template-columns: repeat(2, 1fr); }\n  .stats, .tl-cards, .trace-grid, .detail dl { grid-template-columns: 1fr; }\n  .tabs { overflow-x: auto; padding-left: 8px; }\n  .tabs button { min-width: 84px; }\n  .console-outer { padding: 9px; }\n}\n\n/* a laptop in a video call has about 500px of viewport; below that the\n   panel is too short to read and the fold stops being worth holding */\n@media (max-height: 700px) {\n  .console-view { height: auto; min-height: 0; padding-top: 18px; }\n  .console-view > .wrap { display: block; }\n  .console-outer { display: block; }\n  .panel { height: 520px; flex: none; }\n  .dock { display: none; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  html { scroll-behavior: auto; }\n  *, *::before, *::after {\n    animation-duration: 0.01ms !important;\n    animation-iteration-count: 1 !important;\n    transition-duration: 0.01ms !important;\n  }\n}\n</style>\n</head>\n<body>\n<h1 class=\"sr\">Maverick model capture console</h1>\n\n<header class=\"topbar\" data-section=\"topbar\">\n  <div class=\"wrap\">\n    <span class=\"view\">Capture console <span class=\"ver\">v1.0</span></span>\n    <nav class=\"topnav\" aria-label=\"Console sections\">\n      <button type=\"button\" data-tab=\"t-overview\">Overview</button>\n      <button type=\"button\" data-tab=\"t-anatomy\">Anatomy</button>\n      <button type=\"button\" data-tab=\"t-trace\">Trace</button>\n    </nav>\n    <span class=\"ver\" id=\"clock\">SUBJECT MV-7 \u00b7 SIM</span>\n  </div>\n</header>\n\n<main>\n  <!-- ============ CONSOLE ============ -->\n  <section class=\"console-view\" id=\"console\" style=\"scroll-margin-top: 0\" data-section=\"console\" aria-label=\"Capture console\">\n    <div class=\"wrap\">\n      <div class=\"console-outer\">\n        <div class=\"console\" id=\"consoleBox\">\n\n          <!-- SIDEBAR -->\n          <aside class=\"side\">\n            <div class=\"subject\">\n              <div class=\"subject-frame\">\n                <svg viewBox=\"0 0 200 160\" aria-hidden=\"true\">\n                  <defs>\n                    <linearGradient id=\"sg\" x1=\"0\" y1=\"0\" x2=\"1\" y2=\"1\">\n                      <stop offset=\"0\" stop-color=\"#6366f1\" /><stop offset=\"1\" stop-color=\"#22d3ee\" />\n                    </linearGradient>\n                  </defs>\n                  <g id=\"subjectArt\" fill=\"none\" stroke=\"url(#sg)\" stroke-width=\"1.5\"></g>\n                </svg>\n              </div>\n              <span class=\"subject-tag\">REC \u25cf MV-7_CAPTURE</span>\n            </div>\n\n            <div class=\"side-name\">Maverick</div>\n            <div class=\"side-sub\">Model autopsy console</div>\n\n            <div class=\"transport\" data-component=\"trace-transport\">\n              <div class=\"transport-title\">Run trace</div>\n              <div class=\"transport-read\" id=\"read\">\u2014</div>\n              <div class=\"transport-btns\">\n                <button class=\"tbtn\" type=\"button\" id=\"prev\">\u00ab<span class=\"sr\">Previous step</span></button>\n                <button class=\"tbtn\" type=\"button\" id=\"play\">\u25b8<span class=\"sr\">Play or pause the trace</span></button>\n                <button class=\"tbtn\" type=\"button\" id=\"next\">\u00bb<span class=\"sr\">Next step</span></button>\n              </div>\n              <div class=\"track\"><i id=\"bar\"></i></div>\n              <div class=\"tmeta\"><span id=\"elapsed\">step 1</span><span id=\"total\">of 6</span></div>\n              <label class=\"sr\" for=\"temp\">Sampling temperature</label>\n              <input class=\"temp\" id=\"temp\" type=\"range\" min=\"0\" max=\"1.4\" step=\"0.05\" value=\"0.4\" />\n              <div class=\"tmeta\" style=\"margin-top: 5px\"><span>temp</span><span id=\"tempv\">0.40</span></div>\n            </div>\n\n            <div class=\"manifest\">\n              <div class=\"manifest-rule\" aria-hidden=\"true\"></div>\n              <dl>\n                <dt>Capture</dt><dd>MV-7 / 0142</dd>\n                <dt>Seed</dt><dd>41627</dd>\n                <dt>Revision</dt><dd>b9c4e1f</dd>\n                <dt>Device</dt><dd>sim &middot; cpu</dd>\n                <dt>State</dt><dd id=\"manifestState\">recorded</dd>\n              </dl>\n            </div>\n          </aside>\n\n          <!-- MAIN -->\n          <div class=\"main\">\n            <div class=\"tabs\" role=\"tablist\" aria-label=\"Console sections\">\n              <button role=\"tab\" aria-selected=\"true\" aria-controls=\"p-overview\" id=\"t-overview\"><span>Overview</span></button>\n              <button role=\"tab\" aria-selected=\"false\" aria-controls=\"p-anatomy\" id=\"t-anatomy\"><span>Anatomy</span></button>\n              <button role=\"tab\" aria-selected=\"false\" aria-controls=\"p-timeline\" id=\"t-timeline\"><span>Timeline</span></button>\n              <button role=\"tab\" aria-selected=\"false\" aria-controls=\"p-behaviour\" id=\"t-behaviour\"><span>Behaviour</span></button>\n              <button role=\"tab\" aria-selected=\"false\" aria-controls=\"p-trace\" id=\"t-trace\"><span>Trace</span></button>\n            </div>\n\n            <div class=\"panel\" id=\"panel\">\n              <div class=\"panel-inner\">\n\n                <!-- OVERVIEW -->\n                <section class=\"page on\" id=\"p-overview\" role=\"tabpanel\" aria-labelledby=\"t-overview\">\n                  <div class=\"panel-top\">\n                    <div>\n                      <h3>Subject overview</h3>\n                      <p>MV-7 \u00b7 8 layers sampled \u00b7 capture 00:14:02</p>\n                    </div>\n                    <div class=\"round-set\">\n                      <button class=\"round\" type=\"button\" id=\"skin\" aria-pressed=\"false\">\n                        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M20 13a8 8 0 1 1-9-9 6.5 6.5 0 0 0 9 9z\" /></svg>\n                        <span class=\"sr\">Toggle panel dark mode</span>\n                      </button>\n                      <button class=\"round\" type=\"button\" id=\"toAnatomy\">\n                        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 9V4h5M20 15v5h-5M15 4h5v5M9 20H4v-5\" /></svg>\n                        <span class=\"sr\">Open the anatomy tab</span>\n                      </button>\n                    </div>\n                  </div>\n                  <div class=\"rail\" id=\"rail\"></div>\n                  <div class=\"strip-wrap\">\n                    <div class=\"strip-label\">Captured spans</div>\n                    <div class=\"strip\" id=\"strip\"></div>\n                  </div>\n                  <dl class=\"stats\">\n                    <div class=\"stat\"><dt>Params sampled</dt><dd>8.4<small>B</small></dd></div>\n                    <div class=\"stat\"><dt>Trace length</dt><dd>1,204<small>tok</small></dd></div>\n                    <div class=\"stat\"><dt>Tool calls</dt><dd>3</dd></div>\n                    <div class=\"stat\"><dt>Flagged spans</dt><dd>1</dd></div>\n                  </dl>\n                </section>\n\n                <!-- ANATOMY -->\n                <section class=\"page\" id=\"p-anatomy\" role=\"tabpanel\" aria-labelledby=\"t-anatomy\">\n                  <div class=\"panel-top\">\n                    <div>\n                      <h3>Anatomy</h3>\n                      <p>Tap a point to open that layer</p>\n                    </div>\n                  </div>\n                  <div class=\"anat\">\n                    <div class=\"figure\" id=\"figure\">\n                      <div class=\"fig-inner\" id=\"figInner\"><svg class=\"stack\" viewBox=\"0 0 220 400\" aria-hidden=\"true\" id=\"stackSvg\"></svg></div>\n                    </div>\n                    <div class=\"detail\" id=\"detail\"></div>\n                  </div>\n                </section>\n\n                <!-- TIMELINE -->\n                <section class=\"page\" id=\"p-timeline\" role=\"tabpanel\" aria-labelledby=\"t-timeline\">\n                  <div class=\"panel-top\">\n                    <div>\n                      <h3>Checkpoint timeline</h3>\n                      <p>Every build that reached a capture</p>\n                    </div>\n                  </div>\n                  <div class=\"tl-cards\" id=\"tlCards\"></div>\n                  <div class=\"dots\"><div class=\"dots-pill\" id=\"tlDots\" role=\"group\" aria-label=\"Timeline pages\"></div></div>\n                </section>\n\n                <!-- BEHAVIOUR -->\n                <section class=\"page\" id=\"p-behaviour\" role=\"tabpanel\" aria-labelledby=\"t-behaviour\">\n                  <div class=\"panel-top\">\n                    <div>\n                      <h3>Behaviour</h3>\n                      <p>Measured on the capture, not the marketing</p>\n                    </div>\n                  </div>\n                  <div class=\"beh\">\n                    <div class=\"meters\" id=\"meters\">\n                      <h4>Eval scan</h4>\n                      <div class=\"meter-id\">ID \u00b7 CAPTURE MV-7 / 0142</div>\n                    </div>\n                    <div class=\"beh-notes\">\n                      <div class=\"note\">\n                        <b>What it is good at</b>\n                        <p>Long retrieval-grounded answers, and it says when the context does not contain the answer instead of filling the gap. Two of the three tool calls in this capture were correctly skipped.</p>\n                      </div>\n                      <div class=\"note\">\n                        <b>Where it fails</b>\n                        <p>Confidence stays high while accuracy drops on multi-hop arithmetic. The flagged span at step 4 is the model asserting a computed figure it never computed.</p>\n                        <span class=\"stamp\">Flagged</span>\n                      </div>\n                    </div>\n                  </div>\n                </section>\n\n                <!-- TRACE -->\n                <section class=\"page\" id=\"p-trace\" role=\"tabpanel\" aria-labelledby=\"t-trace\">\n                  <div class=\"panel-top\">\n                    <div>\n                      <h3>Run trace</h3>\n                      <p>Use the transport on the left, or pick a step</p>\n                    </div>\n                  </div>\n                  <div class=\"trace-grid\" id=\"traceGrid\"></div>\n                  <div class=\"now\" id=\"now\">READY</div>\n                </section>\n\n              </div>\n            </div>\n\n            <div class=\"dock\" data-component=\"capture-log\">\n              <div class=\"dock-head\">\n                <span class=\"dock-title\">Capture log</span>\n                <span class=\"dock-meta\">MV-7 &middot; SIM &middot; SEED 41627</span>\n              </div>\n              <ol class=\"dock-log\" id=\"dockLog\" aria-live=\"polite\" aria-label=\"Capture log\"></ol>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n</main>\n\n<!-- The app's status bar. A dashboard has no page footer, but the legal\n     line and the credit still have to live somewhere, so they live here\n     the way a build stamp would. -->\n<footer class=\"statusbar\" data-section=\"status-bar\">\n  <span class=\"sb-left\">\n    <i class=\"sb-dot\" aria-hidden=\"true\"></i>\n    <b>SIM</b> \u00b7 Maverick is a fictional product \u2014 the model, the capture and every\n    reading are invented. Nothing here is real.\n  </span>\n  <span class=\"sb-right\">\n    Shell after a VHS case-file layout by\n    <a href=\"https://codepen.io/mahricodes\" target=\"_blank\" rel=\"noopener\">mahri</a>\n    \u00b7 one file \u00b7 no images \u00b7 no libraries\n  </span>\n</footer>\n\n<script>\n(() => {\n\"use strict\";\nconst $ = (s, r = document) => r.querySelector(s);\nconst $$ = (s, r = document) => [...r.querySelectorAll(s)];\nconst REDUCED = matchMedia(\"(prefers-reduced-motion: reduce)\").matches;\n\n/* ============================================================\n   THE STACK \u2014 what the anatomy figure is made of\n   ============================================================ */\nconst LAYERS = [\n  { id: \"tok\",   name: \"Tokenizer\",    sub: \"byte-pair \u00b7 128k\", y: 352, w: 120,\n    icon: '<path d=\"M4 8h16M4 16h16M9 4v16M15 4v16\"/>',\n    text: \"Where most of the surprise lives. The same sentence can cost thirty percent more tokens in one language than another, and a run that looks expensive is often a tokenisation problem wearing a model costume.\",\n    facts: [[\"Vocab\", \"128,000\"], [\"Bytes/token\", \"3.9\"], [\"Special\", \"14\"], [\"Cost share\", \"\u2014\"]] },\n  { id: \"embed\", name: \"Embedding\",    sub: \"4096-dim\", y: 306, w: 150,\n    icon: '<circle cx=\"12\" cy=\"12\" r=\"3\"/><path d=\"M12 2v5M12 17v5M2 12h5M17 12h5\"/>',\n    text: \"Tokens become positions in a space the model actually reasons over. Nothing here is human-readable, which is exactly why the next four panels exist.\",\n    facts: [[\"Width\", \"4,096\"], [\"Tied\", \"Yes\"], [\"Rotary\", \"\u03b8 10k\"], [\"Drift\", \"0.02\"]] },\n  { id: \"attn\",  name: \"Attention\",    sub: \"32 heads \u00b7 GQA\", y: 248, w: 176,\n    icon: '<path d=\"M4 12h4l3-7 3 14 3-7h3\"/>',\n    text: \"The part everyone means when they say the model 'looked at' something. In this capture, heads 11 and 27 carry almost all of the retrieval grounding \u2014 when they attend to the wrong span, the answer goes wrong with them.\",\n    facts: [[\"Heads\", \"32\"], [\"KV groups\", \"8\"], [\"Window\", \"8,192\"], [\"Cache\", \"412 MB\"]] },\n  { id: \"mlp\",   name: \"Feed forward\", sub: \"SwiGLU \u00b7 14k\", y: 192, w: 176,\n    icon: '<path d=\"M5 19V9M12 19V5M19 19v-7\"/>',\n    text: \"Two thirds of the parameters and almost none of the conversation. This is where most of what the model knows is stored, and why pruning it is how the small version gets small.\",\n    facts: [[\"Hidden\", \"14,336\"], [\"Act\", \"SwiGLU\"], [\"Params\", \"5.6B\"], [\"Sparsity\", \"0%\"]] },\n  { id: \"router\",name: \"Router\",       sub: \"8 experts \u00b7 top-2\", y: 136, w: 150,\n    icon: '<path d=\"M12 3v7M12 14v7M5 10h14M5 10l-2 4M19 10l2 4\"/>',\n    text: \"Picks which experts see the token. A router that collapses onto two favourites looks fine on throughput and quietly loses the capacity you paid for, so its balance is worth watching per capture.\",\n    facts: [[\"Experts\", \"8\"], [\"Active\", \"2\"], [\"Balance\", \"0.91\"], [\"Drop\", \"0.4%\"]] },\n  { id: \"decode\",name: \"Decoder\",      sub: \"temp \u00b7 top-p\", y: 84,  w: 150,\n    icon: '<path d=\"M4 6h16M4 12h10M4 18h7\"/>',\n    text: \"Everything upstream produces a distribution; this turns it into text. Most 'the model is unreliable' reports are a sampling setting, which is why the temperature control sits on the transport rather than buried in a config file.\",\n    facts: [[\"Temp\", \"0.40\"], [\"Top-p\", \"0.92\"], [\"Seed\", \"pinned\"], [\"Beams\", \"1\"]] },\n  { id: \"guard\", name: \"Guard\",        sub: \"post-hoc\", y: 38,  w: 120,\n    icon: '<path d=\"M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z\"/>',\n    text: \"Runs after the decoder and sees only the output, which means it catches unsafe text and never catches an unsafe plan. Useful, and routinely oversold as a safety story.\",\n    facts: [[\"Checks\", \"6\"], [\"Latency\", \"31 ms\"], [\"Tripped\", \"0\"], [\"Mode\", \"Advisory\"]] },\n];\n\n/* ============================================================\n   SUBJECT ART \u2014 a generated capture frame, no photograph\n   ============================================================ */\n(() => {\n  const g = $(\"#subjectArt\");\n  let d = \"\";\n  for (let i = 0; i < 7; i++) {\n    const y = 20 + i * 19;\n    d += `<rect x=\"${58 + (i % 3) * 6}\" y=\"${y}\" width=\"${84 - (i % 3) * 12}\" height=\"12\" rx=\"3\" opacity=\"${0.35 + i * 0.08}\"/>`;\n  }\n  d += '<path d=\"M100 14v132\" stroke-dasharray=\"2 5\" opacity=\".5\"/>';\n  for (let i = 0; i < 26; i++) {\n    const x = 12 + Math.random() * 176, y = 12 + Math.random() * 136;\n    d += `<circle cx=\"${x.toFixed(0)}\" cy=\"${y.toFixed(0)}\" r=\"1\" opacity=\"${(0.2 + Math.random() * 0.5).toFixed(2)}\"/>`;\n  }\n  g.innerHTML = d;\n})();\n\n/* ============================================================\n   TABS\n   ============================================================ */\nconst tabs = $$('[role=\"tab\"]');\nfunction show(id, btn) {\n  $$(\".page\").forEach((p) => p.classList.toggle(\"on\", p.id === \"p-\" + id));\n  tabs.forEach((t) => t.setAttribute(\"aria-selected\", String(t === btn)));\n  const panel = $(\"#panel\");\n  panel.classList.remove(\"glitch\");\n  void panel.offsetWidth;\n  if (!REDUCED) panel.classList.add(\"glitch\");\n  if (id === \"behaviour\") drawMeters();\n}\ntabs.forEach((t) => t.addEventListener(\"click\", () => show(t.id.slice(2), t)));\n$(\"#toAnatomy\").addEventListener(\"click\", () => show(\"anatomy\", $(\"#t-anatomy\")));\ntabs.forEach((t, i) => t.addEventListener(\"keydown\", (e) => {\n  const d = e.key === \"ArrowRight\" ? 1 : e.key === \"ArrowLeft\" ? -1 : 0;\n  if (!d) return;\n  e.preventDefault();\n  const n = tabs[(i + d + tabs.length) % tabs.length];\n  n.focus();\n  show(n.id.slice(2), n);\n}));\n\n/* panel dark mode, from the source's light/dark switch */\n$(\"#skin\").addEventListener(\"click\", (e) => {\n  const box = $(\"#consoleBox\");\n  const on = box.dataset.skin === \"dark\";\n  box.dataset.skin = on ? \"light\" : \"dark\";\n  e.currentTarget.setAttribute(\"aria-pressed\", String(!on));\n});\n\n/* ============================================================\n   OVERVIEW RAIL\n   ============================================================ */\n$(\"#rail\").innerHTML = LAYERS.slice(0, 5).map((l) => `\n  <button class=\"rcard\" type=\"button\" data-layer=\"${l.id}\" aria-pressed=\"false\">\n    <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\">${l.icon}</svg>\n    <b>${l.name}</b><span>${l.sub}</span><em>inspect \u2192</em>\n  </button>`).join(\"\");\n$(\"#rail\").addEventListener(\"click\", (e) => {\n  const b = e.target.closest(\".rcard\");\n  if (!b) return;\n  selectLayer(b.dataset.layer);\n  show(\"anatomy\", $(\"#t-anatomy\"));\n});\n\n/* ============================================================\n   ANATOMY FIGURE + HOTSPOTS\n   ============================================================ */\n(() => {\n  const svg = $(\"#stackSvg\"), inner = $(\"#figInner\");\n  let s = '<path class=\"spine\" d=\"M110 20V380\"/>';\n  LAYERS.forEach((l) => {\n    s += `<rect class=\"blk\" x=\"${110 - l.w / 2}\" y=\"${l.y - 20}\" width=\"${l.w}\" height=\"40\" rx=\"12\"/>`;\n    s += `<text x=\"110\" y=\"${l.y + 4}\" text-anchor=\"middle\">${l.name}</text>`;\n  });\n  svg.innerHTML = s;\n  /* Positioned in percentages of the wrapper that overlays the svg, so nothing\n     has to be measured. The anatomy tab is display:none at startup, and a\n     hidden element reports a clientWidth of zero \u2014 which put every point in\n     the same place the first time this ran. */\n  LAYERS.forEach((l) => {\n    const b = document.createElement(\"button\");\n    b.className = \"pt\";\n    b.type = \"button\";\n    b.dataset.layer = l.id;\n    b.setAttribute(\"aria-pressed\", \"false\");\n    b.innerHTML = `<span class=\"sr\">${l.name}</span>`;\n    b.style.left = ((110 + l.w / 2) / 220 * 100) + \"%\";\n    b.style.top = ((l.y / 400) * 388) + \"px\";\n    inner.appendChild(b);\n  });\n  inner.addEventListener(\"click\", (e) => {\n    const p = e.target.closest(\".pt\");\n    if (p) selectLayer(p.dataset.layer);\n  });\n})();\n\nfunction selectLayer(id) {\n  const l = LAYERS.find((x) => x.id === id) || LAYERS[2];\n  $$(\".pt\").forEach((p) => p.setAttribute(\"aria-pressed\", String(p.dataset.layer === l.id)));\n  $$(\".rcard\").forEach((c) => c.setAttribute(\"aria-pressed\", String(c.dataset.layer === l.id)));\n  $(\"#detail\").innerHTML = `\n    <div class=\"detail-kicker\">Layer \u00b7 ${LAYERS.indexOf(l) + 1} of ${LAYERS.length}</div>\n    <h4>${l.name}</h4>\n    <div class=\"sub\">${l.sub}</div>\n    <p>${l.text}</p>\n    <dl>${l.facts.map((f) => `<div><dt>${f[0]}</dt><dd>${f[1]}</dd></div>`).join(\"\")}</dl>`;\n}\nselectLayer(\"attn\");\n\n/* ============================================================\n   TIMELINE\n   ============================================================ */\nconst CHECKPOINTS = [\n  [[\"mv-7.0\", \"Mar\", \"First capture that survived a full eval sweep. Router balance was still poor and it showed on long contexts.\", 42],\n   [\"mv-7.1\", \"Apr\", \"Retrieval grounding landed. Hallucination rate on the closed-book set halved without touching the weights.\", 61],\n   [\"mv-7.2\", \"Jun\", \"Guard moved post-hoc after it started refusing valid medical questions in the pre-decode position.\", 68],\n   [\"mv-7.3\", \"Aug\", \"Tokenizer swap. Same quality, nineteen percent fewer tokens on non-English prompts.\", 77]],\n  [[\"mv-7.4\", \"Sep\", \"Expert count doubled, active experts held at two. Throughput flat, quality up on code.\", 83],\n   [\"mv-7.5\", \"Oct\", \"Sampling defaults changed after most reliability reports turned out to be temperature.\", 88],\n   [\"mv-7.6\", \"Nov\", \"Long-context window to 8k. Attention heads 11 and 27 took over grounding here.\", 91],\n   [\"mv-7.7\", \"Dec\", \"The capture on this page. One flagged span, three tool calls, two correctly skipped.\", 94]],\n];\nlet tlPage = 0;\nfunction drawTimeline() {\n  $(\"#tlCards\").innerHTML = CHECKPOINTS[tlPage].map((c) => `\n    <article class=\"tlc\">\n      <div class=\"tlc-top\"><b>${c[0]}</b><span>${c[1]}</span></div>\n      <p>${c[2]}</p>\n      <div class=\"tlc-bar\"><i style=\"width:${c[3]}%\"></i></div>\n    </article>`).join(\"\");\n  $(\"#tlDots\").innerHTML = CHECKPOINTS.map((_, i) =>\n    `<button type=\"button\" aria-current=\"${i === tlPage}\"><span class=\"sr\">Page ${i + 1}</span></button>`).join(\"\");\n}\n$(\"#tlDots\").addEventListener(\"click\", (e) => {\n  const b = e.target.closest(\"button\");\n  if (!b) return;\n  tlPage = [...$(\"#tlDots\").children].indexOf(b);\n  drawTimeline();\n});\ndrawTimeline();\n\n/* ============================================================\n   BEHAVIOUR METERS\n   ============================================================ */\nconst METERS = [\n  [\"Grounded answers\", 91, false], [\"Refuses when unsure\", 84, false],\n  [\"Tool choice\", 78, false], [\"Multi-hop arithmetic\", 41, true],\n  [\"Calibration\", 52, true], [\"Instruction following\", 89, false],\n];\nlet metersDrawn = false;\nfunction drawMeters() {\n  if (metersDrawn) return;\n  metersDrawn = true;\n  const host = $(\"#meters\");\n  const id = host.querySelector(\".meter-id\");\n  METERS.forEach((m) => {\n    const d = document.createElement(\"div\");\n    d.className = \"meter\" + (m[2] ? \" warn\" : \"\");\n    d.innerHTML = `<span><b>${m[0]}</b><em>${m[1]}%</em></span><div class=\"bar\"><i></i></div>`;\n    host.insertBefore(d, id);\n  });\n  requestAnimationFrame(() => $$(\"#meters .bar i\").forEach((b, i) => (b.style.width = METERS[i][1] + \"%\")));\n}\n\n/* ============================================================\n   TRACE + TRANSPORT\n   ============================================================ */\nconst STEPS = [\n  [\"Prompt received\", \"1,204 tokens in. Two documents attached, one of them the wrong revision.\", \"tokenizer\", \"12 ms\"],\n  [\"Retrieval\", \"Four spans pulled. Heads 11 and 27 attend almost entirely to spans 2 and 3.\", \"attention\", \"140 ms\"],\n  [\"Tool call skipped\", \"Calculator offered and declined \u2014 the figure was already in span 3.\", \"router\", \"8 ms\"],\n  [\"Assertion\", \"States a computed total it never computed. This is the flagged span.\", \"decoder\", \"96 ms\"],\n  [\"Self-correction\", \"Notices the mismatch two sentences later and restates the figure correctly.\", \"decoder\", \"88 ms\"],\n  [\"Answer emitted\", \"Guard passes. 412 tokens out, one advisory note attached.\", \"guard\", \"31 ms\"],\n];\nlet cur = 0, playing = false, timer = null;\n/* the captured-spans strip mirrors the trace, so clicking one scrubs to it */\n$(\"#strip\").innerHTML = STEPS.map((s, i) => {\n  let pts = \"\";\n  for (let x = 0; x <= 10; x++) {\n    const v = 13 - Math.sin(x * 0.9 + i * 1.7) * 8 - (x === 5 ? i : 0);\n    pts += (x * 5.2).toFixed(1) + \",\" + Math.max(2, Math.min(24, v)).toFixed(1) + \" \";\n  }\n  return `<button type=\"button\" data-step=\"${i}\" aria-current=\"${i === 0}\">\n    <svg viewBox=\"0 0 52 26\" aria-hidden=\"true\"><polyline points=\"${pts.trim()}\"/></svg>\n    <b><em>${String(i + 1).padStart(2, \"0\")}</em> ${s[2]}</b>\n    <span class=\"sr\">${s[0]}</span></button>`;\n}).join(\"\");\n$(\"#strip\").addEventListener(\"click\", (e) => {\n  const b = e.target.closest(\"button\");\n  if (b) go(Number(b.dataset.step));\n});\n\n$(\"#traceGrid\").innerHTML = STEPS.map((s, i) => `\n  <button class=\"step\" type=\"button\" aria-current=\"${i === 0}\">\n    <span class=\"step-n\">STEP ${String(i + 1).padStart(2, \"0\")}</span>\n    <b>${s[0]}</b><p>${s[1]}</p>\n    <span class=\"step-meta\"><span>${s[2]}</span><span>${s[3]}</span></span>\n  </button>`).join(\"\");\nconst stepEls = $$(\"#traceGrid .step\");\n\nfunction render() {\n  const s = STEPS[cur];\n  stepEls.forEach((e, i) => e.setAttribute(\"aria-current\", String(i === cur)));\n  $$(\"#strip button\").forEach((e, i) => e.setAttribute(\"aria-current\", String(i === cur)));\n  $(\"#read\").textContent = \"STEP \" + String(cur + 1).padStart(2, \"0\") + \" \u2014 \" + s[0];\n  $(\"#now\").textContent = \"NOW: \" + s[0].toUpperCase() + \" \u00b7 \" + s[2].toUpperCase() + \" \u00b7 \" + s[3];\n  $(\"#bar\").style.width = ((cur + 1) / STEPS.length) * 100 + \"%\";\n  $(\"#elapsed\").textContent = \"step \" + (cur + 1);\n  $(\"#total\").textContent = \"of \" + STEPS.length;\n  logStep(cur);\n}\n\n/* the dock keeps a running record of the scrub, newest at the foot, so the\n   fold's extra height carries something that actually changes */\nconst dockLog = $(\"#dockLog\");\nlet clock = 842;\nfunction logStep(i) {\n  const s = STEPS[i];\n  clock += 7 + ((i * 13) % 23);\n  const mm = String(Math.floor(clock / 60)).padStart(2, \"0\");\n  const ss = String(clock % 60).padStart(2, \"0\");\n  const li = document.createElement(\"li\");\n  li.innerHTML =\n    '<span class=\"t\">00:' + mm + \":\" + ss + '</span>' +\n    '<span class=\"k\">' + s[2].toUpperCase() + \"</span>\" +\n    \"<span>\" + s[0] + \" \u2014 \" + s[3] + \"</span>\";\n  dockLog.appendChild(li);\n  while (dockLog.children.length > 40) dockLog.removeChild(dockLog.firstChild);\n  dockLog.scrollTop = dockLog.scrollHeight;\n}\nfunction go(i) { cur = (i + STEPS.length) % STEPS.length; render(); }\n$(\"#traceGrid\").addEventListener(\"click\", (e) => {\n  const b = e.target.closest(\".step\");\n  if (b) go(stepEls.indexOf(b));\n});\n$(\"#next\").addEventListener(\"click\", () => go(cur + 1));\n$(\"#prev\").addEventListener(\"click\", () => go(cur - 1));\nfunction setPlaying(on) {\n  playing = on;\n  $(\"#play\").classList.toggle(\"on\", on);\n  $(\"#play\").firstChild.textContent = on ? \"\u275a\u275a\" : \"\u25b8\";\n  clearInterval(timer);\n  if (on) timer = setInterval(() => go(cur + 1), 2200);\n}\n$(\"#play\").addEventListener(\"click\", () => setPlaying(!playing));\n\nconst temp = $(\"#temp\");\nfunction applyTemp() {\n  const v = parseFloat(temp.value);\n  temp.style.setProperty(\"--f\", (v / 1.4) * 100 + \"%\");\n  $(\"#tempv\").textContent = v.toFixed(2);\n  const d = LAYERS.find((l) => l.id === \"decode\");\n  d.facts[0][1] = v.toFixed(2);\n  if ($(\".pt[data-layer='decode']\")?.getAttribute(\"aria-pressed\") === \"true\") selectLayer(\"decode\");\n}\ntemp.addEventListener(\"input\", applyTemp);\napplyTemp();\nrender();\n})();\n/* ============================================================\n   APP CHROME\n   The topbar is part of the console now, not a page nav: its\n   buttons drive the same tablist, and the readout ticks.\n   ============================================================ */\n(() => {\n  const btns = [...document.querySelectorAll(\".topnav button\")];\n  const sync = () => {\n    for (const b of btns) {\n      const tab = document.getElementById(b.dataset.tab);\n      b.setAttribute(\"aria-current\", String(tab?.getAttribute(\"aria-selected\") === \"true\"));\n    }\n  };\n  for (const b of btns) {\n    b.addEventListener(\"click\", () => { document.getElementById(b.dataset.tab)?.click(); sync(); });\n  }\n  for (const t of document.querySelectorAll('[role=\"tab\"]')) t.addEventListener(\"click\", sync);\n  sync();\n\n  const clock = document.getElementById(\"clock\");\n  if (!clock || matchMedia(\"(prefers-reduced-motion: reduce)\").matches) return;\n  let s0 = 842;\n  setInterval(() => {\n    s0 += 1;\n    const mm = String(Math.floor(s0 / 60)).padStart(2, \"0\");\n    const ss = String(s0 % 60).padStart(2, \"0\");\n    clock.textContent = \"SUBJECT MV-7 \u00b7 SIM \u00b7 00:\" + mm + \":\" + ss;\n  }, 1000);\n})();\n\n</script>\n</body>\n</html>\n```");